package com.qpwflshclub.formal_club.social;
import org.junit.jupiter.api.Test;import org.junit.jupiter.api.io.TempDir;import com.fasterxml.jackson.databind.ObjectMapper;import java.nio.file.*;import java.util.*;import java.security.*;import java.security.spec.*;import javax.crypto.KeyAgreement;import static org.junit.jupiter.api.Assertions.*;
class MessageRecoveryTest {
 @TempDir Path root;
 @Test void provisionOfflineAndRestoreAfterRestart()throws Exception{var json=new ObjectMapper();var keys=new MessageKeys(json,root.toString());var service=new MessageRecovery(json,keys,root.toString());String id="a".repeat(64);var pub=service.provision(id);var own=service.get(id);assertNotNull(own);assertEquals(pub.publicKey(),own.publicKey());assertEquals(pub,service.provision(id));byte[] disk=Files.readAllBytes(root.resolve("recovery/"+id+".enc"));assertFalse(new String(disk).contains(own.privateKey()));var restarted=new MessageRecovery(json,new MessageKeys(json,root.toString()),root.toString());assertEquals(own,restarted.get(id));var factory=KeyFactory.getInstance("EC");var a=KeyAgreement.getInstance("ECDH");a.init(factory.generatePrivate(new PKCS8EncodedKeySpec(Base64.getDecoder().decode(own.privateKey()))));a.doPhase(factory.generatePublic(new X509EncodedKeySpec(Base64.getDecoder().decode(pub.publicKey()))),true);assertEquals(32,a.generateSecret().length);String other="b".repeat(64);Files.copy(root.resolve("recovery/"+id+".enc"),root.resolve("recovery/"+other+".enc"));assertThrows(java.io.IOException.class,()->restarted.get(other));}
 @Test void neverReplaceExistingKeyAndRejectMismatchedPair()throws Exception{var json=new ObjectMapper();var keys=new MessageKeys(json,root.toString());var service=new MessageRecovery(json,keys,root.toString());String a="a".repeat(64),b="b".repeat(64),c="c".repeat(64);service.provision(a);service.provision(b);var first=service.get(a);var second=service.get(b);assertThrows(Exception.class,()->service.save(c,new MessageRecovery.Identity(first.publicKey(),second.privateKey())));keys.register(c,first.publicKey());assertEquals(first.publicKey(),service.provision(c).publicKey());assertNull(service.get(c));assertThrows(Exception.class,()->service.save(c,second));service.save(c,first);assertEquals(first,service.get(c));service.remove(c);keys.removeAccount(c);assertNull(keys.get(c));assertNull(service.get(c));}
 @Test void repliesStayInPostAndAccountCleanupPreservesOthers()throws Exception{var store=new SocialStore(new ObjectMapper(),root.toString());var p=store.post("alice","parent");var other=store.post("bob","other");var a=store.reply(p.id(),"bob","comment");var nested=store.reply(p.id(),"alice","answer",a.id());store.likeReply(p.id(),nested.id(),"bob",true);assertEquals(a.id(),store.snapshot().replies().get(1).parentReply());assertThrows(Exception.class,()->store.reply(other.id(),"alice","wrong post",a.id()));store.message("alice","bob","old");store.message("bob","carol","keep");store.like(other.id(),"alice",true);store.removeAccount("alice");assertEquals(1,store.snapshot().posts().size());assertEquals(other.id(),store.snapshot().posts().getFirst().id());assertTrue(store.snapshot().posts().getFirst().likes().isEmpty());assertTrue(store.snapshot().replies().isEmpty());assertEquals(1,store.snapshot().messages().size());assertEquals("keep",store.snapshot().messages().getFirst().text());}
}
